const P0Math={
 softmax(logits,t=1){const scaled=logits.map(x=>x/t),m=Math.max(...scaled),e=scaled.map(x=>Math.exp(x-m)),s=e.reduce((a,b)=>a+b,0);return e.map(x=>x/s);},
 convolution(input,kernel,stride=1,padding=0,dilation=1){const n=input.length,k=kernel.length,o=Math.floor((n+2*padding-dilation*(k-1)-1)/stride)+1;return Array.from({length:o},(_,r)=>Array.from({length:o},(_,c)=>{let sum=0;for(let i=0;i<k;i++)for(let j=0;j<k;j++){const y=r*stride-padding+i*dilation,x=c*stride-padding+j*dilation;sum+=(input[y]?.[x]??0)*kernel[i][j];}return sum;}));},
 gradient(a,mode='normal'){const x=2,b=-.5,w=1.5,target=1,h=a*x+b,y=w*h,error=y-target;return {x,b,w,target,h,y,loss:.5*error*error,da:mode==='detach'?null:error*w*x,dw:mode==='freeze'?null:error*h};},
 accumulated(na,nb,clip){const a=2,b=-4,g=(na*a+nb*b)/(na+nb),bound=x=>Math.max(-clip,Math.min(clip,x));return {weighted:g,naive:(a+b)/2,clipped:bound(g),clippedEarly:(na*bound(a)+nb*bound(b))/(na+nb)};},
 geometry(x,y,mode){const w=320,h=180,t=224;if(mode==='stretch')return {sx:t/w,sy:t/h,dx:0,dy:0,x:x*t/w,y:y*t/h};const scale=mode==='crop'?Math.max(t/w,t/h):Math.min(t/w,t/h),dx=(t-w*scale)/2,dy=(t-h*scale)/2;return {sx:scale,sy:scale,dx,dy,x:x*scale+dx,y:y*scale+dy};},
 queue(delay,hz,horizon=8){const dt=1000/hz,first=Math.min(horizon,Math.ceil(delay/dt));return {dt,first,available:Math.max(0,horizon-first)};},
 bellman(reward,gamma,nextValue,terminated){return reward+gamma*(terminated?0:nextValue);}
};
