const p0Heading=(title,desc)=>`<div class="explorer-title"><h3>${title}</h3></div><p>${desc}</p>`;
function p0Explorer(id){
 if(id==='gradient-flow'||id==='autograd'||id==='matrix-grad')return `<section class="explorer" data-explorer="gradient">${p0Heading('参数冻结与梯度传播','一个三步计算图：h = a×x+b，y = w×h，L = ½(y−target)²。固定 x=2、b=−0.5、w=1.5、target=1，改变 a 和梯度模式。')}<div class="experiment-controls"><label for="p0-grad-a">参数 a <input id="p0-grad-a" type="range" min="-1" max="2" step=".05" value=".5"><output id="p0-grad-a-value">0.50</output></label><label for="p0-grad-mode">模式 <select id="p0-grad-mode"><option value="normal">所有参数参与求导</option><option value="freeze">只冻结 w</option><option value="detach">对 h 执行 detach</option></select></label></div><div class="gradient-nodes" id="p0-gradient-nodes" aria-live="polite"></div><div class="calc-equation" id="p0-gradient-equation"></div><p class="experiment-explanation" id="p0-gradient-note"></p></section>`;
 if(id==='cnn-receptive-field')return `<section class="explorer" data-explorer="convolution">${p0Heading('卷积输出与输入感受野','5×5 单通道输入与 3×3 核。点击输出格子，查看参与计算的输入位置；这是 PyTorch Conv2d 使用的互相关，不翻转卷积核。')}<div class="experiment-controls"><label for="p0-conv-stride">stride <select id="p0-conv-stride"><option>1</option><option>2</option></select></label><label for="p0-conv-padding">padding <select id="p0-conv-padding"><option>0</option><option>1</option></select></label><label for="p0-conv-dilation">dilation <select id="p0-conv-dilation"><option>1</option><option>2</option></select></label><label for="p0-conv-kernel">卷积核 <select id="p0-conv-kernel"><option value="edge">左右边缘</option><option value="mean">均值平滑</option></select></label></div><div class="matrix-layout"><div class="matrix-panel"><h4>输入 5 × 5</h4><div class="experiment-grid" id="p0-conv-input" style="grid-template-columns:repeat(5,1fr)"></div></div><div class="matrix-panel"><h4>卷积核 3 × 3</h4><div class="experiment-grid" id="p0-conv-weights" style="grid-template-columns:repeat(3,1fr)"></div></div><div class="matrix-panel"><h4 id="p0-conv-output-title">输出</h4><div class="experiment-grid" id="p0-conv-output"></div></div></div><div class="calc-equation" id="p0-conv-equation" aria-live="polite"></div><p class="experiment-explanation" id="p0-conv-note"></p></section>`;
 if(id==='softmax-lab'||id==='probability')return `<section class="explorer" data-explorer="softmax">${p0Heading('温度参数与概率分布','三个类别 A/B/C，真实类别固定为 B。输入 logits=[zₐ, 1, −1]，计算 softmax(logits / T) 与 −log p(B)。')}<div class="experiment-controls"><label for="p0-softmax-z">A 的 logit <input id="p0-softmax-z" type="range" min="-4" max="6" step=".1" value="2"><output id="p0-softmax-z-value">2.0</output></label><label for="p0-softmax-temp">温度 T <input id="p0-softmax-temp" type="range" min=".25" max="2" step=".05" value="1"><output id="p0-softmax-temp-value">1.00</output></label></div><div class="bar-chart" id="p0-softmax-bars"></div><div class="viz-metrics" aria-live="polite"><div><small>概率总和</small><strong id="p0-softmax-sum"></strong></div><div><small>真实类别 p(B)</small><strong id="p0-softmax-target"></strong></div><div><small>交叉熵</small><strong id="p0-softmax-loss"></strong></div></div><p class="experiment-explanation">先减去最大 logit 可以稳定计算，同时保持概率不变。标准 CrossEntropyLoss 接收原始 logits；本演示的温度除法是在损失之前显式进行的建模选择。</p></section>`;
 if(id==='tokenizer-autoregressive')return `<section class="explorer" data-explorer="tokens">${p0Heading('自回归预测与标签对齐','教学词表序列：BOS、抓、红杯、ANS、左、夹、EOS、PAD。ANS 之后是回答区；模型前向输入与监督目标错开一位。')}<div class="experiment-controls"><label for="p0-token-offset">标签偏移 <select id="p0-token-offset"><option value="1">+1：正确的下一 token</option><option value="2">+2：故意重复 shift</option></select></label><label><input type="checkbox" id="p0-token-prompt">也监督 prompt（改变训练目标）</label></div><div class="token-matrix" id="p0-token-grid"></div><div class="calc-equation" id="p0-token-equation" aria-live="polite"></div><p class="experiment-explanation">灰色目标不计入 loss，但对应 prompt 仍可作为上下文。PAD 与 EOS 作用不同；不要因为二者共用 ID 就忽略真实 EOS。具体模型若已内部 shift，调用者不要再 shift 一次。</p></section>`;
 if(id==='gradient-accumulation')return `<section class="explorer" data-explorer="accumulation">${p0Heading('梯度累积中的加权归约','两个 micro-batch 的平均梯度分别是 +2 和 −4。改变各自有效标量元素数，比较全局平均、错误的等权平均，以及裁剪的时机。')}<div class="experiment-controls"><label for="p0-accum-a">A 有效元素 <input id="p0-accum-a" type="range" min="1" max="8" step="1" value="6"><output id="p0-accum-a-value">6</output></label><label for="p0-accum-b">B 有效元素 <input id="p0-accum-b" type="range" min="1" max="8" step="1" value="2"><output id="p0-accum-b-value">2</output></label><label for="p0-accum-clip">裁剪阈值 <input id="p0-accum-clip" type="range" min=".5" max="5" step=".5" value="1"><output id="p0-accum-clip-value">1.0</output></label></div><div class="viz-metrics" aria-live="polite"><div><small>按有效元素加权</small><strong id="p0-accum-correct"></strong></div><div><small>错误地等权平均</small><strong id="p0-accum-wrong"></strong></div><div><small>累积完成后裁剪</small><strong id="p0-accum-final"></strong></div></div><div class="calc-equation" id="p0-accum-equation"></div><p class="experiment-explanation" id="p0-accum-note"></p></section>`;
 if(id==='vision-preprocessing')return `<section class="explorer" data-explorer="geometry">${p0Heading('图像变换与标注坐标','原图 320×180，输出 224×224。移动红色关键点，比较拉伸、等比补边与等比中心裁剪。坐标采用连续图像边界约定。')}<div class="experiment-controls"><label for="p0-geo-x">原图 x <input id="p0-geo-x" type="range" min="0" max="320" step="5" value="240"><output id="p0-geo-x-value">240</output></label><label for="p0-geo-mode">处理方式 <select id="p0-geo-mode"><option value="letterbox">等比补边 Letterbox</option><option value="stretch">直接拉伸 Resize</option><option value="crop">等比中心裁剪</option></select></label></div><div class="geometry-layout"><div><h4>原图 · y 固定为 60</h4><svg viewBox="0 0 320 180" id="p0-geo-source" role="img" aria-label="原图中的关键点"></svg></div><div><h4>网络输入 · 224 × 224</h4><svg viewBox="0 0 224 224" id="p0-geo-target" role="img" aria-label="变换后的关键点"></svg></div></div><div class="calc-equation" id="p0-geo-equation" aria-live="polite"></div><p class="experiment-explanation">这里追踪 2D 标注与几何尺度，不模拟真实图像插值。实际实现还需核对像素中心约定、取整、padding、RGB 顺序和归一化。基座坐标系中的物理三维位置不因纯裁图自动改变，但目标可能被裁掉。</p></section>`;
 if(id==='conditioning-fusion')return `<section class="explorer" data-explorer="conditioning">${p0Heading('FiLM 的条件仿射变换','FiLM 的一个通道：y = γh + β。灰线是恒等映射，蓝线由条件生成的 γ、β 决定；多个样本应各自使用自己的条件。')}<div class="experiment-controls"><label for="p0-film-gamma">γ <input id="p0-film-gamma" type="range" min="-2" max="2" step=".1" value="1"><output id="p0-film-gamma-value">1.0</output></label><label for="p0-film-beta">β <input id="p0-film-beta" type="range" min="-2" max="2" step=".1" value="0"><output id="p0-film-beta-value">0.0</output></label></div><svg class="experiment-canvas" viewBox="0 0 560 260" id="p0-film-plot" role="img" aria-label="条件仿射变换"></svg><div class="calc-equation" id="p0-film-equation" aria-live="polite"></div><p class="experiment-explanation">对 [B,T,D] 特征，按样本和通道生成的 γ/β 通常为 [B,1,D]；这是一种条件接口，并不自动保证模型理解了条件语义。AdaLN 则在归一化后的特征上做类似调制，具体实现可能用 1+scale。</p></section>`;
 if(id==='execution-latency')return `<section class="explorer" data-explorer="latency">${p0Heading('动作到达延迟与有效执行区间','观测时间记为 0 ms，模型预测 8 个带目标时间的动作。推理和传输共同造成到达延迟，已经过去的动作不能再当“下一步”执行。')}<div class="experiment-controls"><label for="p0-latency-delay">到达延迟 <input id="p0-latency-delay" type="range" min="0" max="900" step="25" value="250"><output id="p0-latency-delay-value">250 ms</output></label><label for="p0-latency-hz">动作频率 <select id="p0-latency-hz"><option value="5">5 Hz</option><option value="10" selected>10 Hz</option><option value="20">20 Hz</option></select></label></div><div class="timeline-cells" id="p0-latency-cells"></div><div class="viz-metrics" aria-live="polite"><div><small>动作间隔</small><strong id="p0-latency-dt"></strong></div><div><small>已过期个数</small><strong id="p0-latency-expired"></strong></div><div><small>剩余有效动作</small><strong id="p0-latency-available"></strong></div></div><p class="experiment-explanation" id="p0-latency-note"></p></section>`;
 if(id==='returns-bellman')return `<section class="explorer" data-explorer="bellman">${p0Heading('轨迹边界与 Bootstrap 目标','一步 TD 目标：reward + γ × bootstrap。固定 reward=1，真实最终观测的 V=4；重置后新一轮观测的 V=9。')}<div class="experiment-controls"><label for="p0-bellman-gamma">折扣 γ <input id="p0-bellman-gamma" type="range" min="0" max="1" step=".05" value=".9"><output id="p0-bellman-gamma-value">0.90</output></label><label for="p0-bellman-kind">边界类型 <select id="p0-bellman-kind"><option value="continue">继续执行</option><option value="terminated">任务真正终止</option><option value="truncated">外部时间限制截断</option></select></label><label><input type="checkbox" id="p0-bellman-reset">故意错用 reset 后观测</label></div><div class="viz-metrics" aria-live="polite"><div><small>正确 bootstrap 值</small><strong id="p0-bellman-value"></strong></div><div><small>正确 TD 目标</small><strong id="p0-bellman-target"></strong></div><div><small>当前代码选择的目标</small><strong id="p0-bellman-chosen"></strong></div></div><div class="calc-equation" id="p0-bellman-equation"></div><p class="experiment-explanation" id="p0-bellman-note"></p></section>`;
 return '';
}
emlExplorer=function(id){if(id==='attention-mask-only')return originalEmlExplorer('attention');const extra=p0Explorer(id);return extra||originalEmlExplorer(id);};
let p0ConvIndex=0;
const p0val=id=>document.getElementById(id)?.value;
const p0text=(id,text)=>{const el=document.getElementById(id);if(el)el.textContent=text;};
const p0number=v=>v===null?'None':Math.abs(v)<1e-10?'0.000':Number(v).toFixed(3);
function updateP0Gradient(){if(!document.getElementById('p0-grad-a'))return;const a=Number(p0val('p0-grad-a')),mode=p0val('p0-grad-mode'),g=P0Math.gradient(a,mode);p0text('p0-grad-a-value',a.toFixed(2));const cards=[['① h = a×x+b',g.h,'前向：适配器输出'],['② y = w×h',g.y,'前向：乘法骨干'],['③ L = ½(y−1)²',g.loss,'前向：标量损失'],['a.grad',g.da,mode==='detach'?'路径被切断':'损失 → y → h → a'],['w.grad',g.dw,mode==='freeze'?'参数冻结，无 grad':'损失 → y → w'],['∂L/∂y',g.y-1,'反向：预测误差']];document.getElementById('p0-gradient-nodes').innerHTML=cards.map(([name,value,note])=>`<div class="gradient-node"><small>${name}</small><b>${p0number(value)}</b><span>${note}</span></div>`).join('');p0text('p0-gradient-equation',`未断图时：∂L/∂a = (y−1) × w × x = ${(g.y-1).toFixed(3)} × 1.5 × 2 = ${((g.y-1)*3).toFixed(3)}`);p0text('p0-gradient-note',mode==='freeze'?'冻结 w 只是不为 w 累积梯度；为了更新前面的 a，反向仍需经过 w 这个运算。数学上的偏导不因冻结而改变，变的是自动微分记录与更新范围。':mode==='detach'?'把 h.detach() 作为骨干输入后，数值前向完全一样，但 a 到损失的路径不再被记录，所以 a.grad 为 None。不能把 None 一概当作数值为零。':'梯度沿计算图反向传递。改变 a，观察相同结构下梯度方向和大小怎样随误差变化。');}
function updateP0Convolution(){if(!document.getElementById('p0-conv-input'))return;const input=Array.from({length:5},(_,r)=>Array.from({length:5},(_,c)=>c>=2?1+(r===2?1:0):0)),kernel=p0val('p0-conv-kernel')==='mean'?Array.from({length:3},()=>[1/9,1/9,1/9]):[[-1,0,1],[-1,0,1],[-1,0,1]],s=Number(p0val('p0-conv-stride')),p=Number(p0val('p0-conv-padding')),d=Number(p0val('p0-conv-dilation')),out=P0Math.convolution(input,kernel,s,p,d),n=out.length;p0ConvIndex=Math.min(p0ConvIndex,n*n-1);const row=Math.floor(p0ConvIndex/n),col=p0ConvIndex%n,selected=new Set(),terms=[];for(let i=0;i<3;i++)for(let j=0;j<3;j++){const y=row*s-p+i*d,x=col*s-p+j*d;if(y>=0&&y<5&&x>=0&&x<5)selected.add(y*5+x);terms.push(`${input[y]?.[x]??0}×${kernel[i][j]===1/9?'⅑':kernel[i][j]}`);}document.getElementById('p0-conv-input').innerHTML=input.flat().map((v,i)=>`<span class="matrix-cell ${selected.has(i)?'in-window':''}" aria-label="输入 ${Math.floor(i/5)},${i%5} 值 ${v}">${v}</span>`).join('');document.getElementById('p0-conv-weights').innerHTML=kernel.flat().map(v=>`<span class="matrix-cell">${v===1/9?'⅑':v}</span>`).join('');const grid=document.getElementById('p0-conv-output');grid.style.gridTemplateColumns=`repeat(${n},1fr)`;grid.innerHTML=out.flat().map((v,i)=>`<button class="${i===p0ConvIndex?'selected-cell':''}" data-conv-cell="${i}" aria-label="查看输出 ${Math.floor(i/n)},${i%n}" aria-pressed="${i===p0ConvIndex}">${Number.isInteger(v)?v:v.toFixed(2)}</button>`).join('');p0text('p0-conv-output-title',`输出 ${n} × ${n}`);p0text('p0-conv-equation',`输出[${row},${col}] = ${terms.join(' + ')} = ${out[row][col].toFixed(3)}`);p0text('p0-conv-note',`输出边长 = floor((5 + 2×${p} − ${d}×(3−1) − 1) / ${s}) + 1 = ${n}。单层覆盖跨度为 ${d*2+1}×${d*2+1}；dilation>1 时跨度内存在没有采样的位置，padding 超出输入的值为 0。`);}
function updateP0Softmax(){if(!document.getElementById('p0-softmax-z'))return;const z=Number(p0val('p0-softmax-z')),t=Number(p0val('p0-softmax-temp')),p=P0Math.softmax([z,1,-1],t);p0text('p0-softmax-z-value',z.toFixed(1));p0text('p0-softmax-temp-value',t.toFixed(2));document.getElementById('p0-softmax-bars').innerHTML=p.map((v,i)=>`<div class="bar-row"><span>${['A','B · 真实类别','C'][i]}</span><div class="bar-track"><div class="bar-fill" style="width:${v*100}%;${i===1?'background:#4a8a74':''}"></div></div><span class="bar-value">${(100*v).toFixed(2)}%</span></div>`).join('');p0text('p0-softmax-sum',p.reduce((a,b)=>a+b,0).toFixed(4));p0text('p0-softmax-target',p[1].toFixed(4));p0text('p0-softmax-loss',(-Math.log(p[1])).toFixed(4));}
function updateP0Tokens(){if(!document.getElementById('p0-token-grid'))return;const seq=['BOS','抓','红杯','ANS','左','夹','EOS','PAD'],offset=Number(p0val('p0-token-offset')),prompt=document.getElementById('p0-token-prompt').checked;const targets=Array.from({length:7},(_,i)=>seq[i+offset]??'—'),mask=targets.map((t,i)=>i+offset<7&&(prompt||i+offset>=4));const row=(title,cells,classes=[])=>`<div class="token-row"><span>${title}</span>${cells.map((t,i)=>`<span class="${classes[i]||''}">${t}</span>`).join('')}</div>`;document.getElementById('p0-token-grid').innerHTML=row('logits 位置',[0,1,2,3,4,5,6])+row('输入 token',seq.slice(0,7))+row('目标 token',targets,mask.map(x=>x?'supervised-token':'masked-token'))+row('计入 loss',mask.map(x=>x?'1':'0'),mask.map(x=>x?'supervised-token':'masked-token'));p0text('p0-token-equation',offset===1?`正确：位置 3 的输入是 ANS，它的 logits 预测位置 4 的“左”。当前 ${mask.filter(Boolean).length} 个目标计入损失，EOS 包含在监督中。`:`错位示例：位置 3 的 logits 被要求预测“${targets[3]}”，但它本来应该预测“左”。即使 loss 能下降，也是在训练另一个错位目标。`);}
function updateP0Accumulation(){if(!document.getElementById('p0-accum-a'))return;const a=Number(p0val('p0-accum-a')),b=Number(p0val('p0-accum-b')),c=Number(p0val('p0-accum-clip')),g=P0Math.accumulated(a,b,c);p0text('p0-accum-a-value',a);p0text('p0-accum-b-value',b);p0text('p0-accum-clip-value',c.toFixed(1));p0text('p0-accum-correct',g.weighted.toFixed(3));p0text('p0-accum-wrong',g.naive.toFixed(3));p0text('p0-accum-final',g.clipped.toFixed(3));p0text('p0-accum-equation',`正确梯度 = (${a}×2 + ${b}×(−4)) / (${a}+${b}) = ${g.weighted.toFixed(3)}；逐 micro-batch 先裁剪再加权 = ${g.clippedEarly.toFixed(3)}`);p0text('p0-accum-note','这个标量例子对应按有效动作元素 / token 归约。实际全局范数裁剪针对所有参数组成的向量；AMP 必须先完成累积，再 unscale，再裁剪。DDP 还需要把各 rank 的有效计数纳入同一全局分母。');}
function updateP0Geometry(){if(!document.getElementById('p0-geo-source'))return;const x=Number(p0val('p0-geo-x')),g=P0Math.geometry(x,60,p0val('p0-geo-mode')),visible=g.x>=0&&g.x<=224&&g.y>=0&&g.y<=224,art='<rect width="320" height="180" fill="#e4edfa"/><rect x="35" y="40" width="60" height="95" rx="10" fill="#91afd9"/><rect x="185" y="60" width="75" height="75" rx="6" fill="#a4c8bd"/><path d="M0 140 H320 M160 0 V180" stroke="#ccd9eb" stroke-width="2"/>';p0text('p0-geo-x-value',x);document.getElementById('p0-geo-source').innerHTML=art+`<circle cx="${x}" cy="60" r="6" fill="#c45c55"/><text x="8" y="19" font-size="12" fill="#556d91">(${x}, 60)</text>`;document.getElementById('p0-geo-target').innerHTML=`<defs><clipPath id="p0-geo-clip"><rect width="224" height="224"/></clipPath></defs><rect width="224" height="224" fill="#d6dde8"/><g clip-path="url(#p0-geo-clip)"><g transform="translate(${g.dx},${g.dy}) scale(${g.sx},${g.sy})">${art}</g><circle cx="${g.x}" cy="${g.y}" r="5" fill="#c45c55"/></g><text x="8" y="216" font-size="10" fill="#455c7d">${visible?'关键点仍可见':'关键点已被裁出'}</text>`;p0text('p0-geo-equation',`x′ = ${g.sx.toFixed(3)}×${x} + ${g.dx.toFixed(2)} = ${g.x.toFixed(2)}；y′ = ${g.sy.toFixed(3)}×60 + ${g.dy.toFixed(2)} = ${g.y.toFixed(2)}。${visible?'标注仍在目标图内。':'必须更新可见性，不能把越界点作为正常可见标注。'}`);}
function updateP0Conditioning(){if(!document.getElementById('p0-film-plot'))return;const g=Number(p0val('p0-film-gamma')),b=Number(p0val('p0-film-beta')),X=x=>280+x*115,Y=y=>130-y*26;let svg='<line x1="40" y1="130" x2="520" y2="130" stroke="#c6d4e9"/><line x1="280" y1="15" x2="280" y2="245" stroke="#c6d4e9"/>';for(let t=-2;t<=2;t++)svg+=`<text x="${X(t)}" y="147" font-size="11" text-anchor="middle">${t}</text>`;for(let t of [-4,-2,2,4])svg+=`<text x="272" y="${Y(t)+4}" font-size="11" text-anchor="end">${t}</text>`;svg+='<text x="530" y="125" font-size="12">h</text><text x="290" y="17" font-size="12">y</text>';svg+=`<line x1="${X(-1)}" y1="${Y(-1)}" x2="${X(1)}" y2="${Y(1)}" stroke="#b6c0d1" stroke-width="3" stroke-dasharray="6 4"/><line x1="${X(-1)}" y1="${Y(-g+b)}" x2="${X(1)}" y2="${Y(g+b)}" stroke="#3268d8" stroke-width="3"/>`;for(const x of [-1,0,1])svg+=`<circle cx="${X(x)}" cy="${Y(g*x+b)}" r="5" fill="#3268d8"/>`;document.getElementById('p0-film-plot').innerHTML=svg;p0text('p0-film-gamma-value',g.toFixed(1));p0text('p0-film-beta-value',b.toFixed(1));p0text('p0-film-equation',`h = [−1, 0, 1] → y = [${[-1,0,1].map(x=>(g*x+b).toFixed(2)).join(', ')}]。γ=1、β=0 时为恒等变换。`);}
function updateP0Latency(){if(!document.getElementById('p0-latency-delay'))return;const delay=Number(p0val('p0-latency-delay')),hz=Number(p0val('p0-latency-hz')),q=P0Math.queue(delay,hz);p0text('p0-latency-delay-value',delay+' ms');document.getElementById('p0-latency-cells').innerHTML=Array.from({length:8},(_,i)=>`<div class="${i<q.first?'expired':i===q.first?'current':''}">a${i}<small>${Math.round(i*q.dt)} ms</small><small>${i<q.first?'过期':i===q.first?'首个可用':'未来'}</small></div>`).join('');p0text('p0-latency-dt',q.dt.toFixed(0)+' ms');p0text('p0-latency-expired',q.first);p0text('p0-latency-available',q.available);p0text('p0-latency-note',q.available?`到达 ${delay} ms 时，首个不早于到达时间的目标为 a${q.first}。这是假定时钟一致的离散演示；真实执行还要考虑观测新鲜度、队列替换规则与控制器接口。`:'整段动作已过期。应按系统约定请求新计划并保持 / 停止，不能重新从 a0 播放。这个演示不替代机器人控制器的安全约束。');}
function updateP0Bellman(){if(!document.getElementById('p0-bellman-gamma'))return;const gamma=Number(p0val('p0-bellman-gamma')),kind=p0val('p0-bellman-kind'),terminated=kind==='terminated',wrong=document.getElementById('p0-bellman-reset').checked,correct=P0Math.bellman(1,gamma,4,terminated),chosen=P0Math.bellman(1,gamma,wrong?9:4,terminated);p0text('p0-bellman-gamma-value',gamma.toFixed(2));p0text('p0-bellman-value',terminated?'0':'4');p0text('p0-bellman-target',correct.toFixed(3));p0text('p0-bellman-chosen',chosen.toFixed(3));p0text('p0-bellman-equation',`target = 1 + ${gamma.toFixed(2)} × ${terminated?'0':'4'} = ${correct.toFixed(3)}${wrong&&!terminated?'；错用 reset 后状态会把另一条轨迹的价值接进来。':''}`);p0text('p0-bellman-note',terminated?'真正终止时，后续任务回报为零，去掉 bootstrap。即使错误地取了 reset 状态，终止掩码也应阻止它进入当前目标。':kind==='truncated'?'这里的截断指任务本可继续、仅采样器到达外部时间上限，因此使用真实最终观测 bootstrap。若时间上限本就是任务定义的一部分，应把剩余时间纳入状态，并按真正终止处理。':'轨迹正常继续，使用该次转移的 next observation。价值估计一般作为本次 TD 目标的常量处理，不沿目标分支反传。');}
function initP0Explorers(){updateP0Gradient();updateP0Convolution();updateP0Softmax();updateP0Tokens();updateP0Accumulation();updateP0Geometry();updateP0Conditioning();updateP0Latency();updateP0Bellman();}
initExplorers=function(){originalInitExplorers();initP0Explorers();};
function updateP0ById(id){if(id.startsWith('p0-grad-'))updateP0Gradient();else if(id.startsWith('p0-conv-')){p0ConvIndex=0;updateP0Convolution();}else if(id.startsWith('p0-softmax-'))updateP0Softmax();else if(id.startsWith('p0-token-'))updateP0Tokens();else if(id.startsWith('p0-accum-'))updateP0Accumulation();else if(id.startsWith('p0-geo-'))updateP0Geometry();else if(id.startsWith('p0-film-'))updateP0Conditioning();else if(id.startsWith('p0-latency-'))updateP0Latency();else if(id.startsWith('p0-bellman-'))updateP0Bellman();}
document.addEventListener('input',e=>{if(e.target.id?.startsWith('p0-'))updateP0ById(e.target.id);});
document.addEventListener('change',e=>{if(e.target.id?.startsWith('p0-'))updateP0ById(e.target.id);});
document.addEventListener('click',e=>{const cell=e.target.closest('[data-conv-cell]');if(cell){p0ConvIndex=Number(cell.dataset.convCell);updateP0Convolution();}});
